    float c00 = 0.0f;
    float c01 = 0.0f;
    float c10 = 0.0f;
    float c11 = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + 31) / 32; t++) {
        // Load tile from A
        int A_row = by * 32 + ty;
        int A_col = t * 32 + tx;
