#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles
    __shared__ float As[2][16][16];
    __shared__ float Bs[2][16][16];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    float sum = 0.0f;

    // Prefetch first tile
    int A_row = by * 16 + ty;
    int A_col = 0 * 16 + tx;
    if (A_row < N && A_col < N) {
        As[0][ty][tx] = A[A_row * N + A_col];
    } else {
        As[0][ty][tx] = 0.0f;
    }

    int B_row = 0 * 16 + ty;
    int B_col = bx * 16 + tx;
    if (B_row < N && B_col < N) {
        Bs[0][ty][tx] = B[B_row * N + B_col];
    } else {
        Bs[0][ty][tx] = 0.0f;
    }

    __syncthreads();

    int t = 0;
    for (; t < (N + 15) / 16 - 1; t++) {
        // Prefetch next tile
        int next_A_col = (t+1) * 16 + tx;
        if (A_row < N && next_A_col < N) {
            As[(t+1)%2][ty][tx] = A[A_row * N + next_A_col];
        } else {
            As[(t+1)%2][ty][tx] = 0.0f;
        }

        int next_B_row = (t+1) * 16 + ty;
        if (next_B_row < N && B_col < N) {
            Bs[(t+1)%2][ty][tx] = B[next_B_row * N + B_col];
        } else {
            Bs[(t+1)%2][ty][tx] = 0.0f;
        }

        // Compute current tile
        for (int k = 0; k < 16; k++) {
            sum += As[t%2][ty][k] * Bs[t%2][k][tx];
        }

        __syncthreads();
    }

    // Compute last tile
    for (int k = 0; k < 16; k++) {
        sum += As[t%2][ty][k] * Bs[t%2][k][tx];
    }

    // Write result
    int row = by * 16 + ty;
    int col = bx * 16 + tx;

    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

